import pkg_resources  # noqa: F401
from .exceptions import LookupEntryFail


class EntryLookup(object):

    @classmethod
    def in_opr(cls, entries, entry_name):
        """

        lookup class based on `in` operator in dict
        :param dict entries:
                {entry name: class}
        :param str entry_name:
                entry name
        :exception: LookupEntryFail when entry name cannot be found
        :return: True when the entry name is matched
        """
        if entry_name not in entries:
            raise LookupEntryFail("entry_name is {}".format(entry_name))
        return entries[entry_name]


class EntryPoint(object):

    def __init__(self, factory_group_name=None, provider_group_name=None):
        self._factories = {}
        self._providers = {}

        if factory_group_name:
            self._factories = self.__load_entrypoints(factory_group_name)

        if provider_group_name:
            self._providers = self.__load_entrypoints(provider_group_name)

    @staticmethod
    def __load_entrypoints(group_name):
        return dict([(entry_point.name, entry_point.load())  # noqa: C404
                    for entry_point in pkg_resources.iter_entry_points(group=group_name)])

    def create_factory_instance(self, entry_name, lookup=None, **kwargs):
        """

        create factory instance based on the class looked up with `lookup` operator in factory dict
        :param str entry_name:
                entry name
        :param func lookup:
                lookup function, EntryLookup.in_opr acts as default value when lookup is None
        :param kwargs:
                kwargs to initialize factory
        :exception:
                LookupEntryFail when entry name cannot be found
        :return: factory instance
        """
        return self._create_instance(self._factories, entry_name, lookup, **kwargs)

    def create_provider_instance(self, entry_name, lookup=None, **kwargs):
        """

        create provider instance based on the class looked up with `lookup` operator in provider dict
        :param str entry_name:
                entry name
        :param func lookup:
                lookup function, EntryLookup.in_opr acts as default value when lookup is None
        :param kwargs:
                kwargs to initialize provider
        :exception:
                LookupEntryFail when entry name cannot be found
        :return: provider instance
        """
        return self._create_instance(self._providers, entry_name, lookup, **kwargs)

    @staticmethod
    def _create_instance(entries, entry_name, lookup, **kwargs):
        lookup_operation = lookup or EntryLookup.in_opr
        class_instance = lookup_operation(entries, entry_name)
        return class_instance(**kwargs)
